@router.get("/hx/v1/members/{member_id}/permission-card", response_class=HTMLResponse)
def render_member_permission_card(
    request: Request,
    member_id: int,
    templates: Jinja2Templates = Depends(get_templates),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    member = db.query(OrganizationMember).filter(
        OrganizationMember.id == member_id,
        OrganizationMember.org_id == current_user.org_id
    ).first()
    if not member:
        raise HTTPException(status_code=404, detail="Member not found or unauthorized")
    return templates.TemplateResponse(
        "partials/member_permission_card.html",
        {"request": request, "member": member}
    )
